import React from "react";

function Home() {
  return (
    <div className="container">
      <h1 className="header">🍽️ FoodCycle</h1>
      <p>Reduce Waste. Feed People. Connect Communities.</p>
      <p>Join our platform to donate surplus food or buy affordable meals.</p>
    </div>
  );
}

export default Home;
